$ErrorActionPreference = "Stop"

$ProjectRoot = "C:\Projects\SmartTimetable"
$FrontendRoot = Join-Path $ProjectRoot "frontend"
$Target = Join-Path $FrontendRoot "src\pages\Timetable.tsx"
$BackupDir = Join-Path $FrontendRoot "audit_backups"
$Stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$Backup = Join-Path $BackupDir "Timetable.tsx_before_elective_teacher_display_$Stamp.tsx"

if (-not (Test-Path -LiteralPath $Target)) {
    throw "Target file not found: $Target"
}

New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null
Copy-Item -LiteralPath $Target -Destination $Backup -Force

$Payload = @'

'@

try {
    $content = [System.Text.Encoding]::UTF8.GetString(
        [System.Convert]::FromBase64String($Payload)
    )

    [System.IO.File]::WriteAllText(
        $Target,
        $content,
        [System.Text.UTF8Encoding]::new($false)
    )

    Set-Location $FrontendRoot

    Write-Host ""
    Write-Host "Running frontend build..." -ForegroundColor Cyan
    npm run build

    if ($LASTEXITCODE -ne 0) {
        throw "npm run build failed with exit code $LASTEXITCODE"
    }

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " ELECTIVE + TEACHER DISPLAY FIX VERIFIED" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "Grade 10 elective cells display subject codes only."
    Write-Host "Each elective subject displays its teacher code(s)."
    Write-Host "Option labels are removed."
    Write-Host "Full subject names are removed."
    Write-Host "Option 4 explicitly displays BUS and AGRI."
    Write-Host ""
    Write-Host "Frontend build completed successfully." -ForegroundColor Green
    Write-Host "Backup: $Backup"
    Write-Host ""
}
catch {
    Write-Host ""
    Write-Host "BUILD FAILED - restoring previous Timetable.tsx..." -ForegroundColor Red
    Copy-Item -LiteralPath $Backup -Destination $Target -Force
    Write-Host "Original Timetable.tsx restored." -ForegroundColor Yellow
    Write-Host "No backend, solver, or database changes were made." -ForegroundColor Yellow
    Write-Host ""
    throw
}
